package com.adria.transaction.messaging;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;@Service public class TransactionProducer{private final KafkaTemplate<String,TransactionEvent> kafka;public TransactionProducer(KafkaTemplate<String,TransactionEvent> k){kafka=k;}public void publish(TransactionEvent e){kafka.send("bank.transactions.created",e.accountId().toString(),e);}}